\documentclass[article]{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,breaking}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{fontawesome}
\pagestyle{empty}

% ── Web Summit Color Palette ──
% Dark cinematic base with electric accents
\definecolor{darkbg}{HTML}{0A0A1A}          % Deep midnight blue-black
\definecolor{darkblue}{HTML}{0D1B2A}         % Slightly lighter dark blue
\definecolor{neoncyan}{HTML}{00F5FF}         % Electric cyan
\definecolor{neonmagenta}{HTML}{FF2D95}      % Hot magenta
\definecolor{neonlime}{HTML}{39FF14}         % Neon lime
\definecolor{white}{HTML}{FFFFFF}
\definecolor{lightgray}{HTML}{E0E0E0}
\definecolor{mediumgray}{HTML}{888888}
\definecolor{goldaccent}{HTML}{FFD700}        % Gold for VIP/ticket highlight
\definecolor{goldglow}{HTML}{FFA500}         % Orange-gold

\pagecolor{darkbg}
\color{white}

% ── Card Styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=8pt, boxrule=1pt,
    colback=darkblue,
    colframe=neoncyan!40,
    left=20pt, right=16pt, top=16pt, bottom=16pt,
    valign=top, drop shadow={opacity=0.5,color=neoncyan!30},
  },
  accentcard/.style={
    enhanced, arc=8pt, boxrule=1pt,
    colback=darkbg,
    colframe=neonmagenta!50,
    left=20pt, right=16pt, top=16pt, bottom=16pt,
    valign=top, drop shadow={opacity=0.4,color=neonmagenta!30},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=neonmagenta,
    left=20pt, right=16pt, top=16pt, bottom=16pt,
    valign=top, drop shadow={opacity=0.6},
  },
  glowcard/.style={
    enhanced, arc=12pt, boxrule=0pt,
    colback=neoncyan!15,
    colframe=neoncyan,
    frame code={\path node[fit={(interior)},inner sep=0pt,fill=neoncyan!5,draw=none,blur={{shadow xlen=0pt,shadow ylen=0pt}}] {}; },
    left=20pt, right=16pt, top=16pt, bottom=16pt,
    valign=top,
  },
}

% ── Helper Commands ──
\newcommand{\statnumber}[1]{%
  {\fontsize{72}{86}\selectfont\bfseries\color{neoncyan} #1}%
}
\newcommand{\statlabel}[1]{%
  {\fontsize{24}{30}\selectfont\color{lightgray} #1}%
}
\newcommand{\sectiontitle}[1]{%
  {\fontsize{36}{44}\selectfont\bfseries\color{white} #1}%
}
\newcommand{\bigtitle}[1]{%
  {\fontsize{60}{72}\selectfont\bfseries\color{white} #1}%
}
\newcommand{\accenttext}[1]{%
  {\fontsize{28}{36}\selectfont\bfseries\color{neonlime} #1}%
}
\newcommand{\bodytext}[1]{%
  {\fontsize{26}{34}\selectfont\color{lightgray} #1}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=2mm},
]

% ═══════════════════════════════════════════════════════════
% HERO TITLE SECTION (Full Width)
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=darkbg, colframe=none, arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=20pt, bottom=10pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row5}{

  % Main Event Title
  {\fontsize{96}{110}\selectfont\bfseries\color{white} WEB SUMMIT}\\[8pt]
  {\fontsize{56}{68}\selectfont\bfseries\color{neoncyan} LISBON 2026}\\[12pt]

  % Dates and Location
  {\fontsize{32}{40}\selectfont\color{lightgray} NOVEMBER 9--12, 2026}\\[4pt]
  {\fontsize{28}{36}\selectfont\color{mediumgray} LISBON, PORTUGAL}\\[16pt]

  % Subtitle
  {\fontsize{28}{36}\selectfont\color{white!80} ``Where the Future Meets Now''}
}

% ═══════════════════════════════════════════════════════════
% 2-FOR-1 OFFER BANNER (Dominant, Urgent)
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=neonmagenta, colframe=none, arc=0pt, boxrule=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  halign=center, valign=center,
  drop shadow={opacity=0.8,color=neonmagenta}
]{name=offer, column=1, span=3, between=row5 and row8}{

  \begin{minipage}[c]{0.95\linewidth}
    \centering

    % Offer headline
    {\fontsize{64}{76}\selectfont\bfseries\color{white} 2-FOR-1 TICKET OFFER}\\[6pt]

    % Savings highlight
    {\fontsize{80}{96}\selectfont\bfseries\color{goldaccent} SAVE 50\%}\\[8pt]

    % Urgency call
    {\fontsize{28}{36}\selectfont\bfseries\color{white!90} ⏰ 24 HOURS ONLY — REGISTER NOW!}

  \end{minipage}
}

% ═══════════════════════════════════════════════════════════
% STATS ROW (3 Key Metrics)
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=darkblue, colframe=neoncyan!30, arc=8pt, boxrule=1pt,
  left=16pt, right=16pt, top=10pt, bottom=10pt,
  valign=center, drop shadow={opacity=0.3}
]{name=stats1, column=1, span=1, between=row8 and row11}{

  \centering
  {\fontsize{72}{86}\selectfont\bfseries\color{neonlime} 70K+}%
  \vspace{4pt}
  {\fontsize{26}{34}\selectfont\color{lightgray} ATTENDEES}%
  \vspace{8pt}
  {\fontsize{20}{26}\selectfont\color{mediumgray} Worldwide tech leaders}

}

\posterbox[
  enhanced, colback=darkblue, colframe=neoncyan!30, arc=8pt, boxrule=1pt,
  left=16pt, right=16pt, top=10pt, bottom=10pt,
  valign=center, drop shadow={opacity=0.3}
]{name=stats2, column=2, span=1, between=row8 and row11}{

  \centering
  {\fontsize{72}{86}\selectfont\bfseries\color{neoncyan} 4}%
  \vspace{4pt}
  {\fontsize{26}{34}\selectfont\color{lightgray} DAYS}%
  \vspace{8pt}
  {\fontsize{20}{26}\selectfont\color{mediumgray} Nov 9--12, 2026}

}

\posterbox[
  enhanced, colback=darkblue, colframe=neoncyan!30, arc=8pt, boxrule=1pt,
  left=16pt, right=16pt, top=10pt, bottom=10pt,
  valign=center, drop shadow={opacity=0.3}
]{name=stats3, column=3, span=1, between=row8 and row11}{

  \centering
  {\fontsize{72}{86}\selectfont\bfseries\color{goldaccent} 10+}%
  \vspace{4pt}
  {\fontsize{26}{34}\selectfont\color{lightgray} SPEAKERS}%
  \vspace{8pt}
  {\fontsize{20}{26}\selectfont\color{mediumgray} CEOs, world leaders, AI pioneers}

}

% ═══════════════════════════════════════════════════════════
% SPEAKER LINEUP SECTION
% ═══════════════════════════════════════════════════════════
\posterbox[
  glowcard, title={WORLD-CLASS SPEAKERS},
  fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{neoncyan}
]{name=speakers, column=1, span=2, between=row11 and row15}{

  \begin{minipage}[c]{0.98\linewidth}
    \bodytext{Speaker alumni include industry giants and global leaders:}\\[12pt]

    \begin{tabular}{p{0.48\linewidth}p{0.48\linewidth}}
      {\fontsize{28}{36}\selectfont\bfseries\color{white} Sam Altman} &
      {\fontsize{26}{34}\selectfont\color{lightgray} CEO, OpenAI} \\[10pt]
      {\fontsize{28}{36}\selectfont\bfseries\color{white} Geoffrey Hinton} &
      {\fontsize{26}{34}\selectfont\color{lightgray} Godfather of AI, Univ. Toronto} \\[10pt]
      {\fontsize{28}{36}\selectfont\bfseries\color{white} Ursula von der Leyen} &
      {\fontsize{26}{34}\selectfont\color{lightgray} President, European Commission} \\[10pt]
      {\fontsize{28}{36}\selectfont\bfseries\color{white} António Guterres} &
      {\fontsize{26}{34}\selectfont\color{lightgray} Secretary-General, UN} \\[10pt]
      {\fontsize{28}{36}\selectfont\bfseries\color{white} Doug Leone} &
      {\fontsize{26}{34}\selectfont\color{lightgray} Managing Partner, Sequoia Capital} \\
    \end{tabular}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════════
% ECOSYSTEM SECTION
% ═══════════════════════════════════════════════════════════
\posterbox[
  accentcard, title={AN ECOSYSTEM FOR EVERYONE},
  fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{neonmagenta}
]{name=ecosystem, column=3, between=row11 and row15}{

  \bodytext{5 distinct participant categories:}\\[10pt]

  {\fontsize{26}{34}\selectfont\color{white!90} \faicon{rocket} \textbf{STARTUPS}}\\[4pt]
  {\fontsize{22}{28}\selectfont\color{lightgray} Startup programme, funding opportunities}\\[10pt]

  {\fontsize{26}{34}\selectfont\color{white!90} \faicon{users} \textbf{INVESTORS}}\\[4pt]
  {\fontsize{22}{28}\selectfont\color{lightgray} Dedicated VC track \& meetups}\\[10pt]

  {\fontsize{26}{34}\selectfont\color{white!90} \faicon{briefcase} \textbf{PARTNERS}}\\[4pt]
  {\fontsize{22}{28}\selectfont\color{lightgray} Exhibition halls, brand activations}\\[10pt]

  {\fontsize{26}{34}\selectfont\color{white!90} \faicon{microphone} \textbf{MEDIA}}\\[4pt]
  {\fontsize{22}{28}\selectfont\color{lightgray} Press access \& partnerships}\\[10pt]

  {\fontsize{26}{34}\selectfont\color{white!90} \faicon{street-view} \textbf{ATTENDEES}}\\[4pt]
  {\fontsize{22}{28}\selectfont\color{lightgray} Full schedule, Night Summit, meetups}

}

% ═══════════════════════════════════════════════════════════
% TESTIMONIALS SECTION
% ═══════════════════════════════════════════════════════════
\posterbox[
  darkcard, title={WHAT ATTENDEES SAY},
  fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{neonlime}
]{name=testimonials, column=1, span=3, between=row15 and row18}{

  \begin{minipage}[c]{0.32\linewidth}
    \centering
    {\fontsize{20}{26}\selectfont\color{neoncyan} \textit{Brad Smith, President, Microsoft}}\\[8pt]
    {\fontsize{24}{32}\selectfont\color{white} ``Coming to Web Summit is really an opportunity to peer a bit into the future, connect to it, and be part of it.''}
  \end{minipage}
  \hfill
  \begin{minipage}[c]{0.32\linewidth}
    \centering
    {\fontsize{20}{26}\selectfont\color{neoncyan} \textit{Miguel Figueiredo, Siemens}}\\[8pt]
    {\fontsize{24}{32}\selectfont\color{white} ``To hear from today's tech giants' CTOs and CIOs -- not to forget the networking -- it was a pretty amazing day!''}
  \end{minipage}
  \hfill
  \begin{minipage}[c]{0.32\linewidth}
    \centering
    {\fontsize{20}{26}\selectfont\color{neoncyan} \textit{Alicia Tillman, CMO, SAP}}\\[8pt]
    {\fontsize{24}{32}\selectfont\color{white} ``Web Summit is a perfect illustration of the power of community. People rely on communities to educate and to help plan for change.''}
  \end{minipage}

}

% ═══════════════════════════════════════════════════════════
% CALL TO ACTION (Footer)
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=neoncyan, colframe=none, arc=0pt, boxrule=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  halign=center, valign=center,
  drop shadow={opacity=0.7,color=neoncyan}
]{name=cta, column=1, span=3, between=row18 and bottom}{

  \begin{minipage}[c]{0.95\linewidth}
    \centering
    {\fontsize{48}{58}\selectfont\bfseries\color{darkbg} REGISTER NOW}\\[8pt]
    {\fontsize{28}{36}\selectfont\bfseries\color{darkblue} Don't miss the future -- November 9-12, 2026 in Lisbon}
  \end{minipage}

}

\end{tcbposter}
\end{document}

